#[derive(Debug, Clone)]
pub struct Args {
    pub bases: Vec<String>,
    pub protected: Vec<String>,
    pub no_update: bool,
    pub update_interval: Option<u64>,
    pub no_confirm: bool,
    pub no_detach: bool,
    pub delete: Vec<DeleteRange>,
    pub dry_run: bool,
}

pub fn command() -> Command {
    Command::new("git-trim")
        .version("0.4.4")
        .about(ABOUT)
        .long_about(LONG_ABOUT)
        .arg(
