                .long("bases")
                .value_name("BASES")
                .help(BASES_HELP)
                .long_help(BASES_LONG_HELP)
                .action(ArgAction::Append)
                .value_delimiter(','),
        )
        .arg(
            Arg::new("protected")
                .short('p')
                .long("protected")
                .value_name("PROTECTED")
                .help(PROTECTED_HELP)
                .action(ArgAction::Append)
                .value_delimiter(','),
        )
        .arg(
            Arg::new("no_update")
                .long("no-update")
                .help(NO_UPDATE_HELP)
                .action(ArgAction::SetTrue),
