            Arg::new("no_detach")
                .long("no-detach")
                .help(NO_DETACH_HELP)
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("delete")
                .short('d')
                .long("delete")
                .value_name("DELETE")
                .help(DELETE_HELP)
                .long_help(DELETE_LONG_HELP)
                .action(ArgAction::Append)
                .value_delimiter(',')
                .value_parser(clap::value_parser!(DeleteRange)),
        )
        .arg(
            Arg::new("dry_run")
                .long("dry-run")
                .help(DRY_RUN_HELP)
                .action(ArgAction::SetTrue),
        )
}

