#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Scope {
    All,
    Scoped(String),
}

impl Scope {
    pub fn matches(&self, remote: &str) -> bool {
        match self {
            Scope::All => true,
            Scope::Scoped(name) => name == remote,
        }
    }
}

impl fmt::Display for Scope {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Scope::All => write!(f, "*"),
            Scope::Scoped(name) => write!(f, "{}", name),
        }
    }
}

#[derive(Debug, Error)]
pub enum ScopeParseError {
    #[error("Scope is empty")]
    Empty,
}

impl FromStr for Scope {
    type Err = ScopeParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let s = s.trim();
        if s.is_empty() {
            Err(ScopeParseError::Empty)
        } else if s == "*" {
            Ok(Scope::All)
        } else {
            Ok(Scope::Scoped(s.to_owned()))
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum DeleteRange {
    Merged(Scope),
    MergedLocal,
    MergedRemote(Scope),
    Stray,
    Diverged(Scope),
    Local,
    Remote(Scope),
}

#[derive(Debug, Error)]
pub enum DeleteRangeParseError {
    #[error("Invalid delete range format `{0}`")]
    InvalidFormat(String),
    #[error("Scope parse error for delete range while parsing scope: {0}")]
    ScopeParseError(#[source] ScopeParseError),
}

impl FromStr for DeleteRange {
    type Err = DeleteRangeParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let trimmed = s.trim();
        let (range, scope) = match trimmed.split_once(':') {
            Some((range, scope)) => (range.trim(), Some(scope)),
            None => (trimmed, None),
        };
        let parse_scope = |scope: Option<&str>| -> Result<Scope, DeleteRangeParseError> {
            match scope {
                Some(scope) => scope
                    .parse::<Scope>()
                    .map_err(DeleteRangeParseError::ScopeParseError),
                None => Err(DeleteRangeParseError::InvalidFormat(s.to_owned())),
            }
        };
        match (range, scope) {
            ("merged", _) => Ok(DeleteRange::Merged(parse_scope(scope)?)),
            ("merged-remote", _) => Ok(DeleteRange::MergedRemote(parse_scope(scope)?)),
            ("diverged", _) => Ok(DeleteRange::Diverged(parse_scope(scope)?)),
            ("remote", _) => Ok(DeleteRange::Remote(parse_scope(scope)?)),
            ("merged-local", None) => Ok(DeleteRange::MergedLocal),
            ("stray", None) => Ok(DeleteRange::Stray),
            ("local", None) => Ok(DeleteRange::Local),
            _ => Err(DeleteRangeParseError::InvalidFormat(s.to_owned())),
        }
    }
}

impl DeleteRange {
    pub fn to_delete_units(&self) -> Vec<DeleteUnit> {
        match self {
            DeleteRange::Merged(scope) => vec![
                DeleteUnit::MergedLocal,
                DeleteUnit::MergedRemote(scope.clone()),
            ],
            DeleteRange::MergedLocal => vec![DeleteUnit::MergedLocal],
            DeleteRange::MergedRemote(scope) => vec![DeleteUnit::MergedRemote(scope.clone())],
            DeleteRange::Stray => vec![DeleteUnit::Stray],
            DeleteRange::Diverged(scope) => vec![DeleteUnit::Diverged(scope.clone())],
            DeleteRange::Local => vec![DeleteUnit::MergedNonTrackingLocal],
            DeleteRange::Remote(scope) => {
                vec![DeleteUnit::MergedNonUpstreamRemoteTracking(scope.clone())]
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum DeleteUnit {
    MergedLocal,
    MergedRemote(Scope),
    Stray,
    Diverged(Scope),
    MergedNonTrackingLocal,
    MergedNonUpstreamRemoteTracking(Scope),
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct DeleteFilter(HashSet<DeleteUnit>);

impl DeleteFilter {
    pub fn merged_origin() -> Self {
        Self::from_ranges(&[DeleteRange::Merged(Scope::Scoped("origin".to_owned()))])
    }

    pub fn from_ranges(ranges: &[DeleteRange]) -> Self {
        let mut set = HashSet::new();
        for range in ranges {
            for unit in range.to_delete_units() {
                set.insert(unit);
            }
        }
        DeleteFilter(set)
    }

    pub fn delete_merged_local(&self) -> bool {
        self.0.contains(&DeleteUnit::MergedLocal)
    }

    pub fn delete_merged_remote(&self, remote: &str) -> bool {
        self.0.iter().any(|unit| match unit {
            DeleteUnit::MergedRemote(scope) => scope.matches(remote),
            _ => false,
        })
    }

    pub fn delete_stray(&self) -> bool {
        self.0.contains(&DeleteUnit::Stray)
    }

    pub fn delete_diverged(&self, remote: &str) -> bool {
        self.0.iter().any(|unit| match unit {
            DeleteUnit::Diverged(scope) => scope.matches(remote),
            _ => false,
        })
    }

    pub fn delete_merged_non_tracking_local(&self) -> bool {
        self.0.contains(&DeleteUnit::MergedNonTrackingLocal)
    }

    pub fn delete_merged_non_upstream_remote_tracking(&self, remote: &str) -> bool {
        self.0.iter().any(|unit| match unit {
            DeleteUnit::MergedNonUpstreamRemoteTracking(scope) => scope.matches(remote),
            _ => false,
        })
    }

    /// Whether any of the delete ranges applies to tracking branches
    pub fn scans_tracking(&self) -> bool {
        self.0.iter().any(|unit| {
            matches!(
                unit,
                DeleteUnit::MergedLocal
                    | DeleteUnit::MergedRemote(_)
                    | DeleteUnit::Stray
                    | DeleteUnit::Diverged(_)
            )
        })
    }
}
