            .name()
            .ok_or_else(|| anyhow!("non-utf8 refname"))?;
        Ok(Self::new(refname))
    }

    /// Converts the remote tracking branch to the branch on the remote
    /// by reverse-applying fetch refspecs of configured remotes.
    pub fn to_remote_branch(&self, repo: &Repository) -> Result<RemoteBranch> {
        for remote_name in repo.remotes()?.iter().flatten() {
            let remote = repo.find_remote(remote_name)?;
            for refspec in remote.refspecs() {
                if refspec.direction() != Direction::Fetch {
                    continue;
