                if refspec.dst_matches(&self.refname) {
                    let rtransformed = refspec.rtransform(&self.refname)?;
                    let refname = rtransformed
                        .as_str()
                        .ok_or_else(|| anyhow!("non-utf8 refname"))?;
                    return Ok(RemoteBranch {
                        remote: remote_name.to_owned(),
                        refname: refname.to_owned(),
                    });
                }
            }
        }
        Err(anyhow!("remote with matching refspec not found"))
    }

    pub fn remote(&self, repo: &Repository) -> Result<String> {
        Ok(self.to_remote_branch(repo)?.remote)
    }
