pub enum Upstream {
    /// Tracks a branch on a configured remote. `None` when the remote tracking branch is gone.
    Tracking(Option<RemoteTrackingBranch>),
    /// `branch.<name>.remote` is not a configured remote name, e.g. an URL or `.`
    DirectFetch(RemoteBranch),
    /// No upstream configured
    None,
}

pub fn get_upstream(repo: &Repository, branch: &LocalBranch) -> Result<Upstream> {
    let config = repo.config()?;
    let name = branch.short_name();
    let remote_name = match config.get_string(&format!("branch.{}.remote", name)) {
        Ok(value) => value,
        Err(err) if err.code() == ErrorCode::NotFound => return Ok(Upstream::None),
        Err(err) => return Err(err.into()),
    };
    let merge = match config.get_string(&format!("branch.{}.merge", name)) {
        Ok(value) => value,
        Err(err) if err.code() == ErrorCode::NotFound => return Ok(Upstream::None),
        Err(err) => return Err(err.into()),
    };
    if remote_name.is_empty() || merge.is_empty() {
        return Ok(Upstream::None);
    }

    match repo.find_remote(&remote_name) {
        Ok(remote) => {
            for refspec in remote.refspecs() {
                if refspec.direction() != Direction::Fetch {
                    continue;
                }
                if refspec.src_matches(&merge) {
                    let transformed = refspec.transform(&merge)?;
                    let refname = transformed
                        .as_str()
                        .ok_or_else(|| anyhow!("non-utf8 refname"))?;
                    if !refname.starts_with("refs/remotes/") {
                        trace!(
                            "upstream of {} is not a remote tracking branch: {}",
                            branch.refname,
                            refname
                        );
                        return Ok(Upstream::Tracking(None));
                    }
                    return match repo.find_reference(refname) {
                        Ok(_) => Ok(Upstream::Tracking(Some(RemoteTrackingBranch::new(refname)))),
                        Err(err) if err.code() == ErrorCode::NotFound => {
                            Ok(Upstream::Tracking(None))
                        }
                        Err(err) => Err(err.into()),
                    };
                }
            }
            trace!(
                "no matching fetch refspec for upstream of {}: {}/{}",
                branch.refname,
                remote_name,
                merge
            );
            Ok(Upstream::Tracking(None))
        }
        Err(err) if err.code() == ErrorCode::InvalidSpec => Ok(Upstream::DirectFetch(RemoteBranch {
            remote: remote_name,
            refname: merge,
        })),
        Err(err) => Err(err).with_context(|| format!("failed to lookup remote of {}", branch.refname)),
    }
}

pub fn local_branches(repo: &Repository) -> Result<Vec<LocalBranch>> {
    let mut result = Vec::new();
    for branch in repo.branches(Some(BranchType::Local))? {
        let (branch, _) = branch?;
        let reference = branch.get();
        if reference.symbolic_target().is_some() {
            continue;
        }
        result.push(LocalBranch::try_from_reference(reference)?);
    }
    result.sort();
    Ok(result)
}

