use std::io;
use std::process::{Command, ExitStatus, Stdio};

use anyhow::Result;
use log::{log, Level};

fn exit_status_error(status: ExitStatus) -> io::Error {
    match status.code() {
        Some(code) => io::Error::from_raw_os_error(code),
        None => io::Error::new(io::ErrorKind::Other, format!("git exited abnormally: {}", status)),
    }
}

/// Runs a git command with inherited stdio.
pub fn git(args: &[&str], level: Level) -> Result<()> {
    log!(level, "> git {}", args.join(" "));
    let status = Command::new("git")
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status()?;
    if !status.success() {
        return Err(exit_status_error(status).into());
    }
    Ok(())
}

/// Logs a git command that would have been run if it were not a dry run.
pub fn git_dry_run(args: &[&str], level: Level) {
    log!(level, "> git {} (dry-run)", args.join(" "));
}

/// Runs a git command and captures its stdout.
pub fn git_output(args: &[&str], level: Level) -> Result<String> {
    log!(level, "> git {}", args.join(" "));
    let output = Command::new("git")
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .output()?;
    if !output.status.success() {
        return Err(exit_status_error(output.status).into());
    }
    let stdout = String::from_utf8(output.stdout)?;
    for line in stdout.lines() {
        log!(level, "| {}", line);
    }
    Ok(stdout)
}
