#[derive(Debug, Clone)]
pub struct MergeTracker {
    merged_set: Arc<Mutex<HashSet<String>>>,
}

impl MergeTracker {
    pub fn with_base_upstreams(repo: &Repository, bases: &[BaseSpec]) -> Result<Self> {
        info!("Initializing MergeTracker");
        let tracker = MergeTracker {
            merged_set: Arc::new(Mutex::new(HashSet::new())),
        };

        for base in bases {
            let upstream = base.base_upstream();
            debug!("base_upstream: {:?}", upstream);
            tracker.track(repo, &upstream.refname)?;
        }

        let mut merged_locals: HashSet<String> = HashSet::new();
        for base in bases {
            let upstream = base.base_upstream();
            let output = subprocess::git_output(
                &["branch", "--format", "%(refname)", "--merged", &upstream.refname],
                Level::Trace,
            )?;
            for line in output.lines() {
                let refname = line.trim();
                if refname.is_empty() {
                    continue;
                }
                if let BaseSpec::Local { local, .. } = base {
                    if local.refname == refname {
                        continue;
                    }
                }
                merged_locals.insert(refname.to_owned());
            }
        }
        for refname in merged_locals {
            if !refname.starts_with("refs/heads/") {
                continue;
            }
            let reference = repo.find_reference(&refname)?;
            if reference.symbolic_target().is_some() {
                continue;
            }
            debug!("merged_local: {:?}", LocalBranch::new(&refname));
            tracker.track(repo, &refname)?;
        }

        let mut merged_remotes: HashSet<String> = HashSet::new();
        for base in bases {
            let upstream = base.base_upstream();
            let output = subprocess::git_output(
                &[
                    "branch",
                    "--format",
                    "%(refname)",
                    "--remote",
                    "--merged",
                    &upstream.refname,
                ],
                Level::Trace,
            )?;
            for line in output.lines() {
                let refname = line.trim();
                if refname.is_empty() {
                    continue;
                }
                if upstream.refname == refname {
                    continue;
                }
                merged_remotes.insert(refname.to_owned());
            }
        }
        for refname in merged_remotes {
            if !refname.starts_with("refs/remotes/") {
                continue;
            }
            let reference = repo.find_reference(&refname)?;
            if reference.symbolic_target().is_some() {
                continue;
            }
            debug!("merged_remote: {:?}", RemoteTrackingBranch::new(&refname));
            tracker.track(repo, &refname)?;
        }

        Ok(tracker)
    }

    fn track(&self, repo: &Repository, refname: &str) -> Result<()> {
        let oid = resolve_oid(repo, refname)?;
        trace!("track: {}", oid);
        self.merged_set.lock().unwrap().insert(oid.to_string());
        Ok(())
    }

    fn is_tracked(&self, oid: &Oid) -> bool {
        self.merged_set.lock().unwrap().contains(&oid.to_string())
    }

    fn insert(&self, oid: &Oid) {
        self.merged_set.lock().unwrap().insert(oid.to_string());
    }

    /// Checks whether the `refname` is merged into the `base` and remembers the result if merged.
    pub fn check_and_track(&self, repo: &Repository, base: &str, refname: &str) -> Result<bool> {
        let oid = resolve_oid(repo, refname)?;
        if self.is_tracked(&oid) {
            debug!("tracked: {:.7} ({})", oid, refname);
            return Ok(true);
        }

        if is_merged_by_rev_list(base, refname)? {
            debug!("rebase merged: {} -> {}", refname, base);
            self.insert(&oid);
            return Ok(true);
        }

        let squash_oid = create_squash_merge_test_commit(repo, base, &oid)?;
        if is_merged_by_rev_list(base, &squash_oid.to_string())? {
            debug!("squash merged: {} -> {}", refname, base);
            self.insert(&oid);
            return Ok(true);
        }

        Ok(false)
    }
}

fn resolve_oid(repo: &Repository, refname: &str) -> Result<Oid> {
    let object = repo
        .revparse_single(refname)
        .with_context(|| format!("failed to resolve {}", refname))?;
    let commit = object.peel_to_commit()?;
    Ok(commit.id())
}

fn is_merged_by_rev_list(base: &str, commit: &str) -> Result<bool> {
    let range = format!("{}...{}", base, commit);
    let output = subprocess::git_output(
        &[
            "rev-list",
            "--cherry-pick",
            "--right-only",
            "--no-merges",
            "-n1",
            &range,
        ],
        Level::Trace,
    )?;
    Ok(output.trim().is_empty())
}

/// Creates a commit that has the same tree as the `commit` but based directly on the merge base
/// with the `base`, so that squash merges can be detected with `git rev-list --cherry-pick`.
fn create_squash_merge_test_commit(repo: &Repository, base: &str, oid: &Oid) -> Result<Oid> {
    let base_oid = resolve_oid(repo, base)?;
    let merge_base = repo.merge_base(base_oid, *oid)?;
    let commit = repo.find_commit(*oid)?;
    let tree = commit.tree()?;
    let parent = repo.find_commit(merge_base)?;
    let signature = Signature::now("git-trim", "git-trim@squash.merge.test.local")?;
    let squash = repo.commit(
        None,
        &signature,
        &signature,
        "git-trim: squash merge test",
        &tree,
        &[&parent],
    )?;
    Ok(squash)
}
