#[derive(Debug, Clone)]
pub enum BaseSpec {
    Local {
        pattern: String,
        local: LocalBranch,
        upstream: RemoteTrackingBranch,
    },
    Remote {
        pattern: String,
        remote: RemoteTrackingBranch,
    },
}

impl BaseSpec {
    pub fn base_upstream(&self) -> &RemoteTrackingBranch {
        match self {
            BaseSpec::Local { upstream, .. } => upstream,
            BaseSpec::Remote { remote, .. } => remote,
        }
    }

    pub fn is_local_base(&self, branch: &LocalBranch) -> bool {
        match self {
            BaseSpec::Local { local, .. } => local == branch,
            BaseSpec::Remote { .. } => false,
        }
    }

    pub fn is_remote_base(&self, branch: &RemoteTrackingBranch) -> bool {
        self.base_upstream() == branch
    }
}

#[derive(Debug, Clone)]
pub struct TrackingBranchClassificationRequest {
    pub base: RemoteTrackingBranch,
    pub local: LocalBranch,
    pub upstream: Option<RemoteTrackingBranch>,
}

#[derive(Debug, Clone)]
pub struct DirectFetchClassificationRequest {
    pub base: RemoteTrackingBranch,
    pub local: LocalBranch,
    pub remote: RemoteBranch,
}

#[derive(Debug, Clone)]
pub struct NonTrackingBranchClassificationRequest {
    pub base: RemoteTrackingBranch,
    pub local: LocalBranch,
}

#[derive(Debug, Clone)]
pub struct NonUpstreamBranchClassificationRequest {
    pub base: RemoteTrackingBranch,
    pub remote: RemoteTrackingBranch,
}

#[derive(Debug, Clone)]
pub enum ClassificationRequest {
    Tracking(TrackingBranchClassificationRequest),
    DirectFetch(DirectFetchClassificationRequest),
    NonTracking(NonTrackingBranchClassificationRequest),
    NonUpstream(NonUpstreamBranchClassificationRequest),
}

impl fmt::Display for ClassificationRequest {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ClassificationRequest::Tracking(req) => write!(f, "{:#?}", req),
            ClassificationRequest::DirectFetch(req) => write!(f, "{:#?}", req),
            ClassificationRequest::NonTracking(req) => write!(f, "{:#?}", req),
            ClassificationRequest::NonUpstream(req) => write!(f, "{:#?}", req),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum ClassifiedBranch {
    MergedLocal(LocalBranch),
    Stray(LocalBranch),
    MergedRemoteTracking(RemoteTrackingBranch),
    DivergedRemoteTracking {
        local: LocalBranch,
        upstream: RemoteTrackingBranch,
    },
    MergedDirectFetch {
        local: LocalBranch,
        remote: RemoteBranch,
    },
    DivergedDirectFetch {
        local: LocalBranch,
        remote: RemoteBranch,
    },
    MergedNonTrackingLocal(LocalBranch),
    MergedNonUpstreamRemoteTracking(RemoteTrackingBranch),
}

impl ClassifiedBranch {
    pub fn local(&self) -> Option<&LocalBranch> {
        match self {
            ClassifiedBranch::MergedLocal(local)
            | ClassifiedBranch::Stray(local)
            | ClassifiedBranch::MergedNonTrackingLocal(local)
            | ClassifiedBranch::DivergedRemoteTracking { local, .. }
            | ClassifiedBranch::MergedDirectFetch { local, .. }
            | ClassifiedBranch::DivergedDirectFetch { local, .. } => Some(local),
            ClassifiedBranch::MergedRemoteTracking(_)
            | ClassifiedBranch::MergedNonUpstreamRemoteTracking(_) => None,
        }
    }

    pub fn remote_tracking(&self) -> Option<&RemoteTrackingBranch> {
        match self {
            ClassifiedBranch::MergedRemoteTracking(upstream)
            | ClassifiedBranch::MergedNonUpstreamRemoteTracking(upstream)
            | ClassifiedBranch::DivergedRemoteTracking { upstream, .. } => Some(upstream),
            _ => None,
        }
    }

    pub fn remote_branch(&self) -> Option<&RemoteBranch> {
        match self {
            ClassifiedBranch::MergedDirectFetch { remote, .. }
            | ClassifiedBranch::DivergedDirectFetch { remote, .. } => Some(remote),
            _ => None,
        }
    }

    /// State of the local side, for displaying
    pub fn local_state(&self) -> Option<String> {
        match self {
            ClassifiedBranch::MergedLocal(_) | ClassifiedBranch::MergedDirectFetch { .. } => {
                Some("merged".to_owned())
            }
            ClassifiedBranch::Stray(_) => Some("stray".to_owned()),
            ClassifiedBranch::MergedNonTrackingLocal(_) => Some("merged non-tracking".to_owned()),
            ClassifiedBranch::DivergedRemoteTracking { upstream, .. } => {
                Some(format!("diverged with {}", upstream.refname))
            }
            ClassifiedBranch::DivergedDirectFetch { remote, .. } => {
                Some(format!("diverged with {}", remote))
            }
            ClassifiedBranch::MergedRemoteTracking(_)
            | ClassifiedBranch::MergedNonUpstreamRemoteTracking(_) => None,
        }
    }

    /// State of the remote side, for displaying
    pub fn remote_state(&self) -> Option<String> {
        match self {
            ClassifiedBranch::MergedRemoteTracking(_)
            | ClassifiedBranch::MergedDirectFetch { .. } => Some("merged".to_owned()),
            ClassifiedBranch::MergedNonUpstreamRemoteTracking(_) => {
                Some("merged non-upstream".to_owned())
            }
            ClassifiedBranch::DivergedRemoteTracking { local, .. } => {
                Some(format!("diverged with {}", local.refname))
            }
            ClassifiedBranch::DivergedDirectFetch { local, .. } => {
                Some(format!("diverged with {}", local.short_name()))
            }
            ClassifiedBranch::MergedLocal(_)
            | ClassifiedBranch::Stray(_)
            | ClassifiedBranch::MergedNonTrackingLocal(_) => None,
        }
    }

    /// Returns `None` when the delete filter accepts the branch, otherwise the delete range that is missing.
    pub fn missing_delete_range(&self, repo: &Repository, filter: &DeleteFilter) -> Result<Option<String>> {
        let result = match self {
            ClassifiedBranch::MergedLocal(_) => {
                if filter.delete_merged_local() {
                    None
                } else {
                    Some("merged-local".to_owned())
                }
            }
            ClassifiedBranch::Stray(_) => {
                if filter.delete_stray() {
                    None
                } else {
                    Some("stray".to_owned())
                }
            }
            ClassifiedBranch::MergedRemoteTracking(upstream) => {
                let remote = upstream.remote(repo)?;
                if filter.delete_merged_remote(&remote) {
                    None
                } else {
                    Some(format!("merged-remote:{}", remote))
                }
            }
            ClassifiedBranch::DivergedRemoteTracking { upstream, .. } => {
                let remote = upstream.remote(repo)?;
                if filter.delete_diverged(&remote) {
                    None
                } else {
                    Some(format!("diverged:{}", remote))
                }
            }
            ClassifiedBranch::MergedDirectFetch { remote, .. } => {
                if filter.delete_merged_remote(&remote.remote) {
                    None
                } else {
                    Some(format!("merged-remote:{}", remote.remote))
                }
            }
            ClassifiedBranch::DivergedDirectFetch { remote, .. } => {
                if filter.delete_diverged(&remote.remote) {
                    None
                } else {
                    Some(format!("diverged:{}", remote.remote))
                }
            }
            ClassifiedBranch::MergedNonTrackingLocal(_) => {
                if filter.delete_merged_non_tracking_local() {
                    None
                } else {
                    Some("local".to_owned())
                }
            }
            ClassifiedBranch::MergedNonUpstreamRemoteTracking(upstream) => {
                let remote = upstream.remote(repo)?;
                if filter.delete_merged_non_upstream_remote_tracking(&remote) {
                    None
                } else {
                    Some(format!("remote:{}", remote))
                }
            }
        };
        Ok(result)
    }
}

#[derive(Debug, Clone)]
pub struct ClassificationResponse {
    pub message: &'static str,
    pub result: Vec<ClassifiedBranch>,
}

pub struct Classifier<'a> {
    tracker: &'a MergeTracker,
    remote_heads: &'a [RemoteHead],
    requests: Vec<ClassificationRequest>,
}

impl<'a> Classifier<'a> {
    pub fn new(tracker: &'a MergeTracker, remote_heads: &'a [RemoteHead]) -> Self {
        Self {
            tracker,
            remote_heads,
            requests: Vec::new(),
        }
    }

    pub fn queue_request(&mut self, request: ClassificationRequest) {
        trace!("Enqueue #{}: {}", self.requests.len(), request);
        self.requests.push(request);
    }

    pub fn classify(self) -> Result<HashSet<ClassifiedBranch>> {
        info!("Classify {} requests", self.requests.len());
        let total = self.requests.len();
        let queue: Arc<Mutex<Vec<(usize, ClassificationRequest)>>> = Arc::new(Mutex::new(
            self.requests.into_iter().enumerate().rev().collect(),
        ));
        let results: Arc<Mutex<Vec<Option<Result<ClassificationResponse>>>>> =
            Arc::new(Mutex::new((0..total).map(|_| None).collect()));

        let workers = thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
            .min(total.max(1));
        let tracker = self.tracker;
        let remote_heads = self.remote_heads;
        thread::scope(|scope| {
            for _ in 0..workers {
                let queue = Arc::clone(&queue);
                let results = Arc::clone(&results);
                scope.spawn(move || {
                    let repo = match Repository::open_from_env() {
                        Ok(repo) => repo,
                        Err(err) => {
                            let mut results = results.lock().unwrap();
                            if let Some(slot) = results.iter_mut().find(|slot| slot.is_none()) {
                                *slot = Some(Err(err.into()));
                            }
                            return;
                        }
                    };
                    loop {
                        let next = queue.lock().unwrap().pop();
                        let Some((index, request)) = next else {
                            break;
                        };
                        let response = classify_request(&repo, tracker, remote_heads, &request);
                        if let Ok(response) = &response {
                            debug!("Result #{}: {:#?}", index, response);
                        }
                        results.lock().unwrap()[index] = Some(response);
                    }
                });
            }
        });

        let results = Arc::try_unwrap(results)
            .map_err(|_| anyhow::anyhow!("classification results are still shared"))?
            .into_inner()
            .unwrap();
        let mut classified = HashSet::new();
        for result in results {
            let response = result.unwrap_or_else(|| {
                Err(anyhow::anyhow!("classification request was not processed"))
            })?;
            classified.extend(response.result);
        }
        Ok(classified)
    }
}

fn classify_request(
    repo: &Repository,
    tracker: &MergeTracker,
    remote_heads: &[RemoteHead],
    request: &ClassificationRequest,
) -> Result<ClassificationResponse> {
    match request {
        ClassificationRequest::Tracking(req) => classify_tracking(repo, tracker, req),
        ClassificationRequest::DirectFetch(req) => {
            classify_direct_fetch(repo, tracker, remote_heads, req)
        }
        ClassificationRequest::NonTracking(req) => classify_non_tracking(repo, tracker, req),
        ClassificationRequest::NonUpstream(req) => classify_non_upstream(repo, tracker, req),
    }
}

fn classify_tracking(
    repo: &Repository,
    tracker: &MergeTracker,
    req: &TrackingBranchClassificationRequest,
) -> Result<ClassificationResponse> {
    let local_merged = tracker.check_and_track(repo, &req.base.refname, &req.local.refname)?;
    let response = match &req.upstream {
        None => {
            if local_merged {
                ClassificationResponse {
                    message: "local is merged but remote is gone",
                    result: vec![ClassifiedBranch::MergedLocal(req.local.clone())],
                }
            } else {
                ClassificationResponse {
                    message: "local is stray but remote is gone",
                    result: vec![ClassifiedBranch::Stray(req.local.clone())],
                }
            }
        }
        Some(upstream) => {
            let upstream_merged =
                tracker.check_and_track(repo, &req.base.refname, &upstream.refname)?;
            match (local_merged, upstream_merged) {
                (true, true) => ClassificationResponse {
                    message: "local & upstream are merged",
                    result: vec![
                        ClassifiedBranch::MergedLocal(req.local.clone()),
                        ClassifiedBranch::MergedRemoteTracking(upstream.clone()),
                    ],
                },
                (true, false) => ClassificationResponse {
                    message: "local is merged but diverged with upstream",
                    result: vec![ClassifiedBranch::DivergedRemoteTracking {
                        local: req.local.clone(),
                        upstream: upstream.clone(),
                    }],
                },
                (false, true) => ClassificationResponse {
                    message: "upstream is merged, but the local strays",
                    result: vec![
                        ClassifiedBranch::Stray(req.local.clone()),
                        ClassifiedBranch::MergedRemoteTracking(upstream.clone()),
                    ],
                },
                (false, false) => ClassificationResponse {
                    message: "local & upstream are not merged yet",
                    result: vec![],
                },
            }
        }
    };
    Ok(response)
}

fn classify_direct_fetch(
    repo: &Repository,
    tracker: &MergeTracker,
    remote_heads: &[RemoteHead],
    req: &DirectFetchClassificationRequest,
) -> Result<ClassificationResponse> {
    let local_merged = tracker.check_and_track(repo, &req.base.refname, &req.local.refname)?;
    let remote_head = remote_heads
        .iter()
        .find(|head| head.remote == req.remote.remote && head.refname == req.remote.refname);
    let response = match remote_head {
        None => {
            if local_merged {
                ClassificationResponse {
                    message: "local is merged and its upstream is gone",
                    result: vec![ClassifiedBranch::MergedLocal(req.local.clone())],
                }
            } else {
                ClassificationResponse {
                    message: "local is not merged but the remote is gone somehow",
                    result: vec![ClassifiedBranch::Stray(req.local.clone())],
                }
            }
        }
        Some(remote_head) => {
            if local_merged {
                let local_oid = repo.refname_to_id(&req.local.refname)?;
                if local_oid.to_string() == remote_head.commit {
                    ClassificationResponse {
                        message: "local & remote are merged",
                        result: vec![ClassifiedBranch::MergedDirectFetch {
                            local: req.local.clone(),
                            remote: req.remote.clone(),
                        }],
                    }
                } else {
                    ClassificationResponse {
                        message: "local is merged, but diverged with upstream",
                        result: vec![ClassifiedBranch::DivergedDirectFetch {
                            local: req.local.clone(),
                            remote: req.remote.clone(),
                        }],
                    }
                }
            } else {
                ClassificationResponse {
                    message: "local is not merged yet",
                    result: vec![],
                }
            }
        }
    };
    Ok(response)
}

fn classify_non_tracking(
    repo: &Repository,
    tracker: &MergeTracker,
    req: &NonTrackingBranchClassificationRequest,
) -> Result<ClassificationResponse> {
    let merged = tracker.check_and_track(repo, &req.base.refname, &req.local.refname)?;
    let response = if merged {
        ClassificationResponse {
            message: "non-tracking local is merged",
            result: vec![ClassifiedBranch::MergedNonTrackingLocal(req.local.clone())],
        }
    } else {
        ClassificationResponse {
            message: "non-tracking local is not merged",
            result: vec![],
        }
    };
    Ok(response)
}

fn classify_non_upstream(
    repo: &Repository,
    tracker: &MergeTracker,
    req: &NonUpstreamBranchClassificationRequest,
) -> Result<ClassificationResponse> {
    let merged = tracker.check_and_track(repo, &req.base.refname, &req.remote.refname)?;
    let response = if merged {
        ClassificationResponse {
            message: "non-upstream local is merged",
            result: vec![ClassifiedBranch::MergedNonUpstreamRemoteTracking(
                req.remote.clone(),
            )],
        }
    } else {
        ClassificationResponse {
            message: "non-upstream local is not merged",
            result: vec![],
        }
    };
    Ok(response)
}

/// Why a classified branch is not going to be deleted.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum KeepReason {
    Base,
    TracksBase(RemoteTrackingBranch),
    Protected(String),
    DeleteRange(String),
    Head,
    Worktree(String),
}

impl fmt::Display for KeepReason {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            KeepReason::Base => write!(f, "base"),
            KeepReason::TracksBase(upstream) => write!(f, "tracks base `{}`", upstream),
            KeepReason::Protected(pattern) => write!(f, "protected by a pattern `{}`", pattern),
            KeepReason::DeleteRange(range) => {
                write!(f, "delete range `{}` was not given", range)
            }
            KeepReason::Head => write!(f, "HEAD"),
            KeepReason::Worktree(path) => write!(f, "worktree at {}", path),
        }
    }
}

/// The result of applying bases, protection patterns, the delete filter and worktree checks
/// to the classified branches.
#[derive(Debug, Default)]
pub struct TrimPlan {
    pub to_delete: HashSet<ClassifiedBranch>,
    pub kept: Vec<(ClassifiedBranch, KeepReason)>,
}

impl TrimPlan {
    pub fn locals_to_delete(&self) -> HashSet<LocalBranch> {
        self.to_delete
            .iter()
            .filter_map(|branch| branch.local().cloned())
            .collect()
    }

    pub fn remote_trackings_to_delete(&self) -> HashSet<RemoteTrackingBranch> {
        self.to_delete
            .iter()
            .filter_map(|branch| branch.remote_tracking().cloned())
            .collect()
    }

    pub fn remote_branches_to_delete(&self) -> HashSet<RemoteBranch> {
        self.to_delete
            .iter()
            .filter_map(|branch| branch.remote_branch().cloned())
            .collect()
    }

    /// Reasons of kept branches, keyed by the local branch refname
    pub fn kept_locals(&self) -> HashMap<LocalBranch, (String, KeepReason)> {
        let mut result = HashMap::new();
        for (branch, reason) in &self.kept {
            if let (Some(local), Some(state)) = (branch.local(), branch.local_state()) {
                result
                    .entry(local.clone())
                    .or_insert_with(|| (state, reason.clone()));
            }
        }
        result
    }

    pub fn kept_remote_trackings(&self) -> HashMap<RemoteTrackingBranch, (String, KeepReason)> {
        let mut result = HashMap::new();
        for (branch, reason) in &self.kept {
            if let (Some(remote), Some(state)) = (branch.remote_tracking(), branch.remote_state()) {
                result
                    .entry(remote.clone())
                    .or_insert_with(|| (state, reason.clone()));
            }
        }
        result
    }

    pub fn kept_remote_branches(&self) -> HashMap<RemoteBranch, (String, KeepReason)> {
        let mut result = HashMap::new();
        for (branch, reason) in &self.kept {
            if let (Some(remote), Some(state)) = (branch.remote_branch(), branch.remote_state()) {
                result
