#[derive(Debug, Clone)]
pub enum ConfigValue<T> {
    Explicit(T),
    GitConfig(T),
    Implicit(T),
}

impl<T> ConfigValue<T> {
    pub fn is_implicit(&self) -> bool {
        matches!(self, ConfigValue::Implicit(_))
    }

    pub fn is_git_config(&self) -> bool {
