impl<T> std::ops::Deref for ConfigValue<T> {
    type Target = T;

    fn deref(&self) -> &Self::Target {
        match self {
            ConfigValue::Explicit(value)
            | ConfigValue::GitConfig(value)
            | ConfigValue::Implicit(value) => value,
        }
    }
}

#[derive(Debug, Clone)]
pub struct Config {
    pub bases: ConfigValue<HashSet<String>>,
    pub protected: ConfigValue<Vec<String>>,
    pub update: ConfigValue<bool>,
    pub update_interval: ConfigValue<u64>,
    pub confirm: ConfigValue<bool>,
    pub detach: ConfigValue<bool>,
    pub delete: ConfigValue<DeleteFilter>,
}

fn get_comma_separated_multi(config: &git2::Config, key: &str) -> Result<Option<Vec<String>>> {
    let mut values = Vec::new();
    let mut found = false;
    let entries = config.multivar(key, None)?;
    entries.for_each(|entry| {
        found = true;
        if let Some(value) = entry.value() {
            for piece in value.split(',') {
                if !piece.is_empty() {
                    values.push(piece.to_owned());
                }
            }
        }
    })?;
    if found {
        Ok(Some(values))
    } else {
        Ok(None)
    }
}

fn get_bool(config: &git2::Config, key: &str) -> Result<Option<bool>> {
    match config.get_bool(key) {
        Ok(value) => Ok(Some(value)),
        Err(err) if err.code() == ErrorCode::NotFound => Ok(None),
        Err(err) => Err(err.into()),
    }
}

fn get_i64(config: &git2::Config, key: &str) -> Result<Option<i64>> {
    match config.get_i64(key) {
        Ok(value) => Ok(Some(value)),
        Err(err) if err.code() == ErrorCode::NotFound => Ok(None),
        Err(err) => Err(err.into()),
    }
}

/// Finds the default bases: local branches that track `refs/remotes/*/HEAD`.
/// When no local branch tracks the remote HEAD, the remote tracking branch itself is used.
fn default_bases(repo: &Repository) -> Result<HashSet<String>> {
    let mut bases = HashSet::new();
    for remote_name in repo.remotes()?.iter().flatten() {
        let head_refname = format!("refs/remotes/{}/HEAD", remote_name);
        let head = match repo.find_reference(&head_refname) {
            Ok(reference) => reference,
            Err(err) if err.code() == ErrorCode::NotFound => continue,
            Err(err) => return Err(err.into()),
        };
        let target = match head.symbolic_target() {
            Some(target) => target.to_owned(),
            None => continue,
        };

        let mut found = false;
        for branch in repo.branches(Some(BranchType::Local))? {
            let (branch, _) = branch?;
            let upstream = match branch.upstream() {
                Ok(upstream) => upstream,
                Err(_) => continue,
            };
            if upstream.get().name() == Some(target.as_str()) {
                if let Some(name) = branch.name()? {
                    bases.insert(name.to_owned());
                    found = true;
                }
            }
        }
        if !found {
            bases.insert(target);
        }
    }
    Ok(bases)
}

pub fn get(repo: &Repository, args: &Args) -> Result<Config> {
    let config = repo.config()?;

    let bases = if !args.bases.is_empty() {
        ConfigValue::Explicit(args.bases.iter().cloned().collect())
    } else if let Some(values) = get_comma_separated_multi(&config, "trim.bases")? {
        ConfigValue::GitConfig(values.into_iter().collect())
    } else {
        ConfigValue::Implicit(default_bases(repo)?)
    };

    let protected = if !args.protected.is_empty() {
        ConfigValue::Explicit(args.protected.clone())
    } else if let Some(values) = get_comma_separated_multi(&config, "trim.protected")? {
        ConfigValue::GitConfig(values)
    } else {
        ConfigValue::Implicit(Vec::new())
    };

    let update = if args.no_update {
        ConfigValue::Explicit(false)
    } else if let Some(value) = get_bool(&config, "trim.update")? {
        ConfigValue::GitConfig(value)
    } else {
        ConfigValue::Implicit(true)
    };

    let update_interval = if let Some(value) = args.update_interval {
        ConfigValue::Explicit(value)
    } else if let Some(value) = get_i64(&config, "trim.updateInterval")? {
