//! Shell-style wildcard matching in the spirit of `fnmatch(3)` without `FNM_PATHNAME`:
//! `*` and `?` also match `/`, bracket expressions support negation with `!` or `^`,
//! ranges, POSIX character classes such as `[:alpha:]`, and `\` escapes the next character.

pub fn matches(pattern: &str, text: &str) -> bool {
    let pattern: Vec<char> = pattern.chars().collect();
    let text: Vec<char> = text.chars().collect();
    match_here(&pattern, &text) == MatchResult::Matched
}

#[derive(Debug, PartialEq, Eq)]
enum MatchResult {
    Matched,
    NoMatch,
    /// the pattern is malformed, which never matches
    Abort,
}

fn match_here(mut pattern: &[char], mut text: &[char]) -> MatchResult {
    while let Some(&p) = pattern.first() {
        match p {
            '*' => {
                // collapse consecutive stars
                while pattern.first() == Some(&'*') {
                    pattern = &pattern[1..];
                }
                if pattern.is_empty() {
                    return MatchResult::Matched;
                }
                for start in 0..=text.len() {
                    match match_here(pattern, &text[start..]) {
                        MatchResult::NoMatch => continue,
                        other => return other,
                    }
                }
                return MatchResult::NoMatch;
            }
            '?' => {
                if text.is_empty() {
                    return MatchResult::NoMatch;
                }
                pattern = &pattern[1..];
                text = &text[1..];
            }
            '[' => {
                let Some(&t) = text.first() else {
                    return MatchResult::NoMatch;
                };
                match match_bracket(&pattern[1..], t) {
                    Some((matched, rest)) => {
                        if !matched {
                            return MatchResult::NoMatch;
                        }
                        pattern = rest;
                        text = &text[1..];
                    }
                    None => return MatchResult::Abort,
                }
            }
            '\\' => {
                let Some(&escaped) = pattern.get(1) else {
                    return MatchResult::Abort;
                };
                if text.first() != Some(&escaped) {
                    return MatchResult::NoMatch;
                }
                pattern = &pattern[2..];
                text = &text[1..];
            }
            _ => {
                if text.first() != Some(&p) {
                    return MatchResult::NoMatch;
                }
                pattern = &pattern[1..];
                text = &text[1..];
            }
        }
    }
    if text.is_empty() {
        MatchResult::Matched
    } else {
        MatchResult::NoMatch
    }
}

/// Matches a bracket expression. `pattern` starts right after the opening `[`.
/// Returns whether `c` matched and the remaining pattern after the closing `]`,
/// or `None` if the bracket expression is malformed.
fn match_bracket(pattern: &[char], c: char) -> Option<(bool, &[char])> {
    let mut i = 0;
    let negated = match pattern.first() {
        Some('!') | Some('^') => {
            i += 1;
            true
        }
        _ => false,
    };
    let mut matched = false;
    let mut first = true;
    loop {
        let &p = pattern.get(i)?;
        if p == ']' && !first {
            return Some((matched != negated, &pattern[i + 1..]));
        }
        first = false;
        if p == '[' && pattern.get(i + 1) == Some(&':') {
            // POSIX character class
            let rest = &pattern[i + 2..];
            if let Some(end) = rest.windows(2).position(|w| w == [':', ']']) {
                let class: String = rest[..end].iter().collect();
                if class_matches(&class, c)? {
                    matched = true;
                }
                i += 2 + end + 2;
                continue;
            }
        }
        let mut lo = p;
        if lo == '\\' {
            i += 1;
            lo = *pattern.get(i)?;
        }
        i += 1;
        if pattern.get(i) == Some(&'-') && pattern.get(i + 1).map_or(false, |&n| n != ']') {
            let mut hi = *pattern.get(i + 1)?;
            i += 2;
            if hi == '\\' {
                hi = *pattern.get(i)?;
                i += 1;
            }
            if lo <= c && c <= hi {
                matched = true;
            }
        } else if lo == c {
            matched = true;
        }
    }
}

fn class_matches(class: &str, c: char) -> Option<bool> {
    let result = match class {
        "alnum" => c.is_ascii_alphanumeric(),
        "alpha" => c.is_ascii_alphabetic(),
        "blank" => c == ' ' || c == '\t',
        "cntrl" => c.is_ascii_control(),
        "digit" => c.is_ascii_digit(),
        "graph" => c.is_ascii_graphic(),
        "lower" => c.is_ascii_lowercase(),
        "print" => c.is_ascii_graphic() || c == ' ',
        "punct" => c.is_ascii_punctuation(),
        "space" => c.is_ascii_whitespace() || c == '\x0b',
        "upper" => c.is_ascii_uppercase(),
        "xdigit" => c.is_ascii_hexdigit(),
        _ => return None,
    };
    Some(result)
}

#[cfg(test)]
mod tests {
    use super::matches;

    #[test]
    fn basics() {
        assert!(matches("*", "origin/feature-diverged"));
        assert!(matches("*/feature-merged", "refs/heads/feature-merged"));
        assert!(matches("feature-[md]*", "feature-merged"));
        assert!(!matches("feature-{merged,diverged}", "feature-merged"));
        assert!(matches("fea?ure-merged", "feature-merged"));
        assert!(matches("f[[:alpha:]]ature-merged", "feature-merged"));
        assert!(!matches("feature-merged[", "feature-merged"));
        assert!(!matches("feature-merged]", "feature-merged"));
        assert!(matches("feature-merge[]d]", "feature-merged"));
        assert!(!matches("feature-merge[!]d]", "feature-merged"));
        assert!(matches("feature-merged**", "feature-merged"));
        assert!(matches("[!a]*", "feature-merged"));
        assert!(!matches("feature-\\*", "feature-merged"));
        assert!(matches("feature-\\*", "feature-*"));
        assert!(!matches("FEATURE-*", "feature-merged"));
        assert!(matches("feature-merge[a-z]", "feature-merged"));
        assert!(!matches("feature-merged/", "feature-merged"));
    }
}
