use std::thread::{self, JoinHandle};

use anyhow::{anyhow, Result};
use git2::{ErrorCode, Repository};
use log::Level;

use crate::branch::RemoteTrackingBranch;
use crate::subprocess;

/// Fetches the HEAD of each remote in background with `git ls-remote --symref <remote> HEAD`
/// so that stale `refs/remotes/<remote>/HEAD`s can be reported afterwards.
pub struct RemoteHeadChangeChecker {
    handles: Vec<(String, JoinHandle<Result<Option<String>>>)>,
}

impl RemoteHeadChangeChecker {
    pub fn spawn(repo: &Repository) -> Result<Self> {
        let mut handles = Vec::new();
        for remote_name in repo.remotes()?.iter().flatten() {
            let remote_name = remote_name.to_owned();
            let name = remote_name.clone();
            let handle = thread::spawn(move || -> Result<Option<String>> {
                let output = subprocess::git_output(
                    &["ls-remote", "--symref", &name, "HEAD"],
                    Level::Trace,
                )?;
                for line in output.lines() {
                    if let Some(rest) = line.strip_prefix("ref: ") {
                        let mut parts = rest.split('\t');
                        let target = parts.next().unwrap_or("");
                        let refname = parts.next().unwrap_or("");
                        if refname == "HEAD" && !target.is_empty() {
                            return Ok(Some(target.to_owned()));
                        }
                    }
                }
                Ok(None)
            });
            handles.push((remote_name, handle));
        }
        Ok(Self { handles })
    }

    pub fn check_and_notify(self, repo: &Repository) -> Result<()> {
        let mut out_of_sync: Vec<(String, String, String)> = Vec::new();
        for (remote_name, handle) in self.handles {
            let remote_head = handle
                .join()
                .map_err(|_| anyhow!("ls-remote thread panicked"))??;
            let Some(remote_head) = remote_head else {
                continue;
            };
            let local_head_refname = format!("refs/remotes/{}/HEAD", remote_name);
            let local_head = match repo.find_reference(&local_head_refname) {
                Ok(reference) => reference,
                Err(err) if err.code() == ErrorCode::NotFound => continue,
                Err(err) => return Err(err.into()),
            };
            let Some(target) = local_head.symbolic_target() else {
                continue;
            };
            if !target.starts_with("refs/remotes/") {
                continue;
            }
            let local_target = RemoteTrackingBranch::new(target).to_remote_branch(repo)?;
            if local_target.refname != remote_head {
                out_of_sync.push((remote_name, local_target.refname, remote_head));
            }
        }

        if out_of_sync.is_empty() {
            return Ok(());
        }

        eprintln!(
            "You are using default base branches, which is deduced from `refs/remotes/*/HEAD`s."
        );
        eprintln!("However, they seems to be out of sync.");
        for (remote_name, local, remote) in &out_of_sync {
            eprintln!(" * {}: {} -> {}", remote_name, local, remote);
        }
        eprintln!("You can sync them with these commands:");
        for (remote_name, _, _) in &out_of_sync {
            eprintln!(" > git remote set-head {} --auto", remote_name);
        }
        eprintln!("Or you can set base branches manually:");
        eprintln!(
            " * `git config trim.bases develop,master` will set base branches for git-trim for a repository."
        );
        eprintln!(
            " * `git config --global trim.bases develop,master` will set base branches for `git-trim` globally."
        );
        eprintln!(
            " * `git trim --bases develop,master` will temporarily set base branches for `git-trim`"
        );
        Ok(())
    }
}
