cd /workspace && cat > src/main.rs <<'EOF'
mod args;
mod branch;
mod config;
mod confirm;
mod core;
mod merge_tracker;
mod remote_head_change_checker;
mod subprocess;
mod wildmatch;

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::thread;
use std::time::{Duration, SystemTime};

use anyhow::{anyhow, Result};
use git2::{ErrorCode, Repository};
use log::{debug, info, trace, Level};

use crate::args::DeleteFilter;
use crate::branch::{
    get_upstream, local_branches, remote_tracking_branches, LocalBranch, RemoteBranch,
    RemoteHead, RemoteTrackingBranch, Upstream,
};
use crate::config::{Config, ConfigValue};
use crate::core::{
    BaseSpec, ClassificationRequest, ClassifiedBranch, Classifier,
    DirectFetchClassificationRequest, KeepReason, NonTrackingBranchClassificationRequest,
    NonUpstreamBranchClassificationRequest, TrackingBranchClassificationRequest, TrimPlan,
};
use crate::merge_tracker::MergeTracker;
use crate::remote_head_change_checker::RemoteHeadChangeChecker;

const VERSION: &str = "";
const COMMIT_DATE: &str = "2026-06-12T00:30:53.000000000Z";
const TARGET_TRIPLE: &str = "x86_64-unknown-linux-gnu";

fn main() -> Result<()> {
    env_logger::init();
    let args = args::parse();

    info!("VERSION: {}", VERSION);
    info!("COMMIT_DATE: {}", COMMIT_DATE);
    info!("TARGET_TRIPLE: {}", TARGET_TRIPLE);

    let repo = Repository::open_from_env()?;
    if repo.remotes()?.is_empty() {
        return Err(anyhow!("git-trim requires at least one remote"));
    }

    let config = config::get(&repo, &args)?;
    info!("config: {:?}", config);

    if config.bases.is_empty() {
        print_no_base_help(&repo, &config)?;
        return Err(anyhow!("No base branch is found!"));
    }

    let mut remote_head_checker = None;
    if *config.update && should_update(&repo, *config.update_interval)? {
        remote_head_checker = Some(RemoteHeadChangeChecker::spawn(&repo)?);
        if args.dry_run {
            subprocess::git_dry_run(&["remote", "update", "--prune"], Level::Info);
        } else {
            subprocess::git(&["remote", "update", "--prune"], Level::Info)?;
        }
        println!();
    }

    let bases = resolve_bases(&repo, &config.bases)?;
    trace!("bases: {:#?}", bases);

    let branches = Branches::collect(&repo)?;
    debug!("tracking_branches: {:#?}", branches.tracking);
    debug!("direct_fetch_branches: {:#?}", branches.direct_fetch);
    debug!("non_tracking_branches: {:#?}", branches.non_tracking);
    debug!("non_upstream_branches: {:#?}", branches.non_upstream);

    let remote_heads = get_remote_heads(&branches.direct_fetch)?;
    debug!("remote_heads: {:#?}", remote_heads);

    let tracker = MergeTracker::with_base_upstreams(&repo, &bases)?;

    info!("Enqueue classification requests");
    let mut classifier = Classifier::new(&tracker, &remote_heads);
    let mut skipped = Skipped::default();

    if config.delete.scans_tracking() {
        for (local, upstream) in &branches.tracking {
            for base in &bases {
                classifier.queue_request(ClassificationRequest::Tracking(
                    TrackingBranchClassificationRequest {
                        base: base.base_upstream().clone(),
                        local: local.clone(),
                        upstream: upstream.clone(),
                    },
                ));
            }
        }
        for (local, remote) in &branches.direct_fetch {
            for base in &bases {
                classifier.queue_request(ClassificationRequest::DirectFetch(
                    DirectFetchClassificationRequest {
                        base: base.base_upstream().clone(),
                        local: local.clone(),
                        remote: remote.clone(),
                    },
                ));
            }
        }
    } else {
        skipped.tracking = branches.tracking.clone();
        skipped
            .tracking
            .extend(branches.direct_fetch.iter().map(|(local, _)| (local.clone(), None)));
    }

    if config.delete.delete_merged_non_tracking_local() {
        for local in &branches.non_tracking {
            for base in &bases {
                classifier.queue_request(ClassificationRequest::NonTracking(
                    NonTrackingBranchClassificationRequest {
                        base: base.base_upstream().clone(),
                        local: local.clone(),
                    },
                ));
            }
        }
    } else {
        skipped.non_tracking = branches.non_tracking.clone();
    }

    for base in &bases {
        for remote_tracking in &branches.non_upstream {
            let remote = remote_tracking.remote(&repo)?;
            if config
                .delete
                .delete_merged_non_upstream_remote_tracking(&remote)
            {
                classifier.queue_request(ClassificationRequest::NonUpstream(
                    NonUpstreamBranchClassificationRequest {
                        base: base.base_upstream().clone(),
                        remote: remote_tracking.clone(),
                    },
                ));
            } else {
                skipped.non_upstream.insert(remote_tracking.clone());
            }
        }
    }

    let classified = classifier.classify()?;

    let worktrees = get_worktrees()?;
    let head_branch = get_head_branch(&repo)?;

    let plan = make_plan(
        &repo,
        &config,
        &bases,
        &branches,
        &classified,
        &worktrees,
        head_branch.as_ref(),
    )?;

    print_summary(&repo, &bases, &branches, &plan, &skipped)?;

    let locals_to_delete = plan.locals_to_delete();
    let remote_trackings_to_delete = plan.remote_trackings_to_delete();
    let remote_branches_to_delete = plan.remote_branches_to_delete();

    let nothing_to_delete = locals_to_delete.is_empty()
        && remote_trackings_to_delete.is_empty()
        && remote_branches_to_delete.is_empty();

    if !nothing_to_delete {
        if !args.dry_run && *config.confirm {
            let confirmed = confirm::confirm("Confirm?")?;
            if !confirmed {
                println!("Cancelled");
                return Ok(());
            }
        }

        delete_remote_branches(
            &repo,
            &remote_trackings_to_delete,
            &remote_branches_to_delete,
            args.dry_run,
        )?;

        if let Some(head) = &head_branch {
            if locals_to_delete.contains(head) && *config.detach {
                detach_head(&repo, head, args.dry_run)?;
            }
        }

        delete_local_branches(&locals_to_delete, args.dry_run)?;
    }

    if let Some(checker) = remote_head_checker {
        checker.check_and_notify(&repo)?;
    }

    Ok(())
}

fn print_no_base_help(repo: &Repository, config: &Config) -> Result<()> {
    if config.bases.is_git_config() {
        eprintln!(
            "I found that `git config trim.bases` is empty! Try any following commands to set valid bases:"
        );
        eprintln!(" * `git config trim.bases develop,master` for a repository.");
        eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
        eprintln!(" * `git trim --bases develop,master` to set temporarily.");
        return Ok(());
    }

    eprintln!("I can't detect base branch! Try following any resolution:");
    let remotes = repo.remotes()?;
    if remotes.len() == 1 {
        let remote = remotes.get(0).unwrap_or("origin");
        eprintln!(
            " * `git remote set-head {} --auto` will help `git-trim` to automatically",
            remote
        );
        eprintln!("   detect the base branch.");
        eprintln!(
            "   If you see `{}/HEAD set to <base branch>` in the output of the previous",
            remote
        );
        eprintln!(
            "   command, then `git branch --set-upstream {}/<base branch> <base branch>`",
            remote
        );
        eprintln!("   to set an upstream branch for <base branch> if exists.");
    } else {
        eprintln!(
            " * `git remote set-head <remote> --auto` will help `git-trim` to automatically"
        );
        eprintln!("   detect the base branch.");
        eprintln!("   Following command will sync all remotes for you:");
        eprintln!("   `for REMOTE in $(git remote); do git remote set-head \"$REMOTE\" --auto; done`");
        eprintln!("   Pick an appropriate one in mind if you see multiple `<remote>/HEAD set to");
        eprintln!("   <base branch>` in the output of the previous command.");
        eprintln!(
            "   Then `git branch --set-upstream <remote>/<base branch> <base branch>` to set"
        );
        eprintln!("   an upstream branch for <base branch> if exists.");
    }
    println!("You also can set bases manually with any of following commands:");
    eprintln!(" * `git config trim.bases develop,master` for a repository.");
    eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
    eprintln!(" * `git trim --bases develop,master` to set temporarily.");
    Ok(())
}

/// Decides whether to run `git remote update --prune`, respecting the update interval
/// measured from the last modification of `FETCH_HEAD`.
fn should_update(repo: &Repository, interval: u64) -> Result<bool> {
    if interval == 0 {
        return Ok(true);
    }

    let config = repo.config()?;
    let fetch_prune = match config.get_bool("fetch.prune") {
        Ok(value) => value,
        Err(err) if err.code() == ErrorCode::NotFound => false,
        Err(err) => return Err(err.into()),
    };
    if !fetch_prune {
        trace!("`git config fetch.prune` is false. force update");
        return Ok(true);
    }

    let fetch_head = repo.path().join("FETCH_HEAD");
    let metadata = match std::fs::metadata(&fetch_head) {
        Ok(metadata) => metadata,
        Err(_) => return Ok(true),
    };
    let modified = metadata.modified()?;
    let elapsed = match SystemTime::now().duration_since(modified) {
        Ok(elapsed) => elapsed,
        Err(_) => return Ok(true),
    };
    Ok(elapsed >= Duration::from_secs(interval))
}

fn resolve_bases(repo: &Repository, patterns: &HashSet<String>) -> Result<Vec<BaseSpec>> {
    let mut bases = Vec::new();
    for pattern in patterns {
        let reference = match repo.resolve_reference_from_short_name(pattern) {
            Ok(reference) => reference,
            Err(err) if err.code() == ErrorCode::NotFound => continue,
            Err(err) => return Err(err.into()),
        };
        let refname = match reference.name() {
            Some(name) => name.to_owned(),
            None => continue,
        };
        if refname.starts_with("refs/heads/") {
            let local = LocalBranch::new(&refname);
            match get_upstream(repo, &local)? {
                Upstream::Tracking(Some(upstream)) => bases.push(BaseSpec::Local {
                    pattern: pattern.clone(),
                    local,
                    upstream,
                }),
                _ => continue,
            }
        } else if refname.starts_with("refs/remotes/") {
            if reference.symbolic_target().is_some() {
                continue;
            }
            bases.push(BaseSpec::Remote {
                pattern: pattern.clone(),
                remote: RemoteTrackingBranch::new(&refname),
            });
        }
    }
    Ok(bases)
}

#[derive(Debug, Default)]
struct Branches {
    tracking: Vec<(LocalBranch, Option<RemoteTrackingBranch>)>,
    direct_fetch: Vec<(LocalBranch, RemoteBranch)>,
    non_tracking: Vec<LocalBranch>,
    non_upstream: Vec<RemoteTrackingBranch>,
}

impl Branches {
    fn collect(repo: &Repository) -> Result<Self> {
        let mut branches = Branches::default();
        let mut upstreams = HashSet::new();
        for local in local_branches(repo)? {
            match get_upstream(repo, &local)? {
                Upstream::Tracking(upstream) => {
                    if let Some(upstream) = &upstream {
                        upstreams.insert(upstream.clone());
                    }
                    branches.tracking.push((local, upstream));
                }
                Upstream::DirectFetch(remote) => branches.direct_fetch.push((local, remote)),
                Upstream::None => branches.non_tracking.push(local),
            }
        }
        for remote_tracking in remote_tracking_branches(repo)? {
            if !upstreams.contains(&remote_tracking) {
                branches.non_upstream.push(remote_tracking);
            }
        }
        Ok(branches)
    }
}

fn get_remote_heads(direct_fetch: &[(LocalBranch, RemoteBranch)]) -> Result<Vec<RemoteHead>> {
    let remotes: BTreeSet<String> = direct_fetch
        .iter()
        .map(|(_, remote)| remote.remote.clone())
        .collect();
    let mut handles = Vec::new();
    for remote in remotes {
        handles.push(thread::spawn(move || -> Result<Vec<RemoteHead>> {
            let output = subprocess::git_output(&["ls-remote", "--heads", &remote], Level::Trace)?;
            let mut heads = Vec::new();
            for line in output.lines() {
                let mut parts = line.split('\t');
                let (Some(commit), Some(refname)) = (parts.next(), parts.next()) else {
                    continue;
                };
                heads.push(RemoteHead {
                    remote: remote.clone(),
                    refname: refname.to_owned(),
                    commit: commit.to_owned(),
                });
            }
            Ok(heads)
        }));
    }
    let mut result = Vec::new();
    for handle in handles {
        let heads = handle
            .join()
            .map_err(|_| anyhow!("ls-remote thread panicked"))??;
        result.extend(heads);
    }
    Ok(result)
}

#[derive(Debug, Default)]
struct Skipped {
    tracking: Vec<(LocalBranch, Option<RemoteTrackingBranch>)>,
    non_tracking: Vec<LocalBranch>,
    non_upstream: HashSet<RemoteTrackingBranch>,
}

/// Worktrees other than the current HEAD: branch refname -> worktree path
fn get_worktrees() -> Result<HashMap<String, String>> {
    let output = subprocess::git_output(&["worktree", "list", "--porcelain"], Level::Trace)?;
    let mut result = HashMap::new();
    let mut path: Option<String> = None;
    for line in output.lines() {
        if let Some(rest) = line.strip_prefix("worktree ") {
            path = Some(rest.to_owned());
        } else if let Some(branch) = line.strip_prefix("branch ") {
            if let Some(path) = &path {
                result.insert(branch.to_owned(), path.clone());
            }
        } else if line.is_empty() {
            path = None;
        }
    }
    Ok(result)
}

fn get_head_branch(repo: &Repository) -> Result<Option<LocalBranch>> {
    let head = match repo.head() {
        Ok(head) => head,
        Err(err) if err.code() == ErrorCode::UnbornBranch || err.code() == ErrorCode::NotFound => {
            return Ok(None)
        }
        Err(err) => return Err(err.into()),
    };
    if !head.is_branch() {
        return Ok(None);
    }
    match head.name() {
        Some(name) if name.starts_with("refs/heads/") => Ok(Some(LocalBranch::new(name))),
        _ => Ok(None),
    }
}

fn protected_by(patterns: &[String], names: &[&str]) -> Option<String> {
    for pattern in patterns {
        for name in names {
            if wildmatch::matches(pattern, name) {
                return Some(pattern.clone());
            }
        }
    }
    None
}

fn local_protected_by(patterns: &[String], local: &LocalBranch) -> Option<String> {
    protected_by(patterns, &[local.short_name(), &local.refname])
}

fn remote_tracking_protected_by(
    patterns: &[String],
    remote: &RemoteTrackingBranch,
) -> Option<String> {
    protected_by(patterns, &[remote.short_name(), &remote.refname])
}

fn make_plan(
    repo: &Repository,
    config: &Config,
    bases: &[BaseSpec],
    branches: &Branches,
    classified: &HashSet<ClassifiedBranch>,
    worktrees: &HashMap<String, String>,
    head_branch: Option<&LocalBranch>,
) -> Result<TrimPlan> {
    let upstream_of: HashMap<&LocalBranch, &RemoteTrackingBranch> = branches
        .tracking
        .iter()
        .filter_map(|(local, upstream)| upstream.as_ref().map(|upstream| (local, upstream)))
        .collect();

    let mut plan = TrimPlan::default();
    let filter: &DeleteFilter = &config.delete;

    // sort for deterministic processing; the sets involved are unordered
    let mut classified: Vec<&ClassifiedBranch> = classified.iter().collect();
    classified.sort_by_key(|branch| format!("{:?}", branch));

    for branch in classified {
        // bases are never deleted
        if let Some(local) = branch.local() {
            if bases.iter().any(|base| base.is_local_base(local)) {
                plan.kept.push((branch.clone(), KeepReason::Base));
                continue;
            }
            if let Some(upstream) = upstream_of.get(local) {
                if let Some(base) = bases.iter().find(|base| {
                    matches!(base, BaseSpec::Remote { .. }) && base.is_remote_base(upstream)
                }) {
                    plan.kept.push((
                        branch.clone(),
                        KeepReason::TracksBase(base.base_upstream().clone()),
                    ));
                    continue;
                }
            }
        }
        if let Some(remote) = branch.remote_tracking() {
            if bases.iter().any(|base| base.is_remote_base(remote)) {
                plan.kept.push((branch.clone(), KeepReason::Base));
                continue;
            }
        }

        // protected patterns
        let mut protected = None;
        if let Some(local) = branch.local() {
            protected = local_protected_by(&config.protected, local);
        }
        if protected.is_none() {
            if let Some(remote) = branch.remote_tracking() {
                protected = remote_tracking_protected_by(&config.protected, remote);
            }
        }
        if let Some(pattern) = protected {
            plan.kept
                .push((branch.clone(), KeepReason::Protected(pattern)));
            continue;
        }

        // delete ranges
        let missing = branch.missing_delete_range(repo, filter)?;
        trace!("Delete range result: {:?} => {:?}", branch, missing);
        if let Some(range) = missing {
            plan.kept
                .push((branch.clone(), KeepReason::DeleteRange(range)));
            continue;
        }

        // checked out branches
        if let Some(local) = branch.local() {
            if Some(local) == head_branch {
                if !*config.detach {
                    plan.kept.push((branch.clone(), KeepReason::Head));
                    continue;
                }
            } else if let Some(path) = worktrees.get(&local.refname) {
                plan.kept
                    .push((branch.clone(), KeepReason::Worktree(path.clone())));
                continue;
            }
        }

        plan.to_delete.insert(branch.clone());
    }

    Ok(plan)
}

fn format_kept(state: &str, reason: &KeepReason, shorten_base: bool) -> String {
    match reason {
        KeepReason::Base | KeepReason::TracksBase(_) if shorten_base && state == "merged" => {
            format!("[{}]", reason)
        }
        _ => format!("[{}, but: {}]", state, reason),
    }
}

fn print_summary(
    repo: &Repository,
    bases: &[BaseSpec],
    branches: &Branches,
    plan: &TrimPlan,
    skipped: &Skipped,
) -> Result<()> {
    let _ = bases;
    let locals_to_delete = plan.locals_to_delete();
    let remote_trackings_to_delete = plan.remote_trackings_to_delete();
    let kept_locals = plan.kept_locals();
    let kept_remote_trackings = plan.kept_remote_trackings();
    let kept_remote_branches = plan.kept_remote_branches();

    let skipped_tracking: HashSet<&LocalBranch> =
        skipped.tracking.iter().map(|(local, _)| local).collect();
    let skipped_tracking_upstreams: HashSet<&RemoteTrackingBranch> = skipped
        .tracking
        .iter()
        .filter_map(|(_, upstream)| upstream.as_ref())
        .collect();
    let skipped_non_tracking: HashSet<&LocalBranch> = skipped.non_tracking.iter().collect();

    let mut has_skipped_tracking = false;
    let mut has_skipped_non_tracking = false;
    let mut has_skipped_non_upstream = false;

    println!("Branches that will remain:");
    println!("  local branches:");
    let mut all_locals: Vec<&LocalBranch> = Vec::new();
    all_locals.extend(branches.tracking.iter().map(|(local, _)| local));
    all_locals.extend(branches.direct_fetch.iter().map(|(local, _)| local));
    all_locals.extend(branches.non_tracking.iter());
    all_locals.sort();
    for local in all_locals {
        if locals_to_delete.contains(local) {
            continue;
        }
        if skipped_tracking.contains(local) {
            has_skipped_tracking = true;
            println!("    {} *1", local);
        } else if skipped_non_tracking.contains(local) {
            has_skipped_non_tracking = true;
            println!("    {} *2", local);
        } else if let Some((state, reason)) = kept_locals.get(local) {
            println!("    {} {}", local, format_kept(state, reason, true));
        } else {
            println!("    {}", local);
        }
    }

    println!("  remote references:");
    let mut all_remote_trackings: Vec<&RemoteTrackingBranch> = Vec::new();
    all_remote_trackings.extend(
        branches
            .tracking
            .iter()
            .filter_map(|(_, upstream)| upstream.as_ref()),
    );
    all_remote_trackings.extend(branches.non_upstream.iter());
    all_remote_trackings.sort();
    all_remote_trackings.dedup();
    for remote in all_remote_trackings {
        if remote_trackings_to_delete.contains(remote) {
            continue;
        }
        if skipped_tracking_upstreams.contains(remote) {
            has_skipped_tracking = true;
            println!("    {} *1", remote);
        } else if skipped.non_upstream.contains(remote) {
            has_skipped_non_upstream = true;
            println!("    {} *3", remote);
        } else if let Some((state, reason)) = kept_remote_trackings.get(remote) {
            println!("    {} {}", remote, format_kept(state, reason, true));
        } else {
            println!("    {}", remote);
        }
    }
    let kept_remote_branches: BTreeMap<&RemoteBranch, &(String, KeepReason)> =
        kept_remote_branches.iter().collect();
    for (remote, (state, reason)) in kept_remote_branches {
        println!("    {} {}", remote, format_kept(state, reason, false));
    }

    if has_skipped_tracking || has_skipped_non_tracking || has_skipped_non_upstream {
        println!("  Some branches are skipped. Consider following to scan them:");
        if has_skipped_tracking {
            let hint = if skipped.tracking.iter().all(|(_, upstream)| upstream.is_none()) {
                "merged-local".to_owned()
            } else {
                "merged:*".to_owned()
            };
            println!("    *1: Add `--delete '{}'` flag.", hint);
        }
        if has_skipped_non_tracking {
            println!(
                "    *2: Set an upstream to make it a tracking branch or add `--delete 'local'` flag."
            );
        }
        if has_skipped_non_upstream {
            let hint = if skipped.non_upstream.len() == 1 {
                let remote = skipped.non_upstream.iter().next().unwrap();
                format!("remote:{}", remote.remote(repo)?)
            } else {
                "remote:*".to_owned()
            };
            println!(
                "    *3: Make it upstream of a tracking branch or add `--delete '{}'` flag.",
                hint
            );
        }
    }
    println!();

    // branches to delete
    let mut merged_locals: BTreeMap<&LocalBranch, bool> = BTreeMap::new();
    let mut merged_remotes: BTreeMap<RemoteBranch, bool> = BTreeMap::new();
    let mut stray_locals: BTreeSet<&LocalBranch> = BTreeSet::new();
    let mut diverged_remotes: BTreeSet<RemoteBranch> = BTreeSet::new();
    for branch in &plan.to_delete {
        match branch {
            ClassifiedBranch::MergedLocal(local) => {
                merged_locals.entry(local).or_insert(false);
            }
            ClassifiedBranch::Stray(local) => {
                stray_locals.insert(local);
            }
            ClassifiedBranch::MergedRemoteTracking(upstream) => {
                merged_remotes
                    .entry(upstream.to_remote_branch(repo)?)
                    .or_insert(false);
            }
            ClassifiedBranch::DivergedRemoteTracking { local, upstream } => {
                merged_locals.entry(local).or_insert(false);
                diverged_remotes.insert(upstream.to_remote_branch(repo)?);
            }
            ClassifiedBranch::MergedDirectFetch { local, remote } => {
                merged_locals.entry(local).or_insert(false);
                diverged_remotes.insert(remote.clone());
            }
            ClassifiedBranch::DivergedDirectFetch { local, remote } => {
                merged_locals.entry(local).or_insert(false);
                diverged_remotes.insert(remote.clone());
            }
            ClassifiedBranch::MergedNonTrackingLocal(local) => {
                merged_locals.insert(local, true);
            }
            ClassifiedBranch::MergedNonUpstreamRemoteTracking(upstream) => {
                merged_remotes.insert(upstream.to_remote_branch(repo)?, true);
            }
        }
    }

    if !merged_locals.is_empty() {
        println!("Delete merged local branches:");
        for (local, non_tracking) in &merged_locals {
            if *non_tracking {
                println!("  - {} (non-tracking)", local);
            } else {
                println!("  - {}", local);
            }
        }
    }
    if !merged_remotes.is_empty() {
        println!("Delete merged remote refs:");
        for (remote, non_upstream) in &merged_remotes {
            if *non_upstream {
                println!("  - {} (non-upstream)", remote);
            } else {
                println!("  - {}", remote);
            }
        }
    }
    if !stray_locals.is_empty() {
        println!("Delete stray local branches:");
        for local in &stray_locals {
            println!("  - {}", local);
        }
    }
    if !diverged_remotes.is_empty() {
        println!("Delete diverged remote refs:");
        for remote in &diverged_remotes {
            println!("  - {}", remote);
        }
    }

    Ok(())
}

fn delete_remote_branches(
    repo: &Repository,
    remote_trackings: &HashSet<RemoteTrackingBranch>,
    remote_branches: &HashSet<RemoteBranch>,
    dry_run: bool,
) -> Result<()> {
    let mut per_remote: HashMap<String, HashSet<String>> = HashMap::new();
    for remote_tracking in remote_trackings {
        let remote_branch = remote_tracking.to_remote_branch(repo)?;
        per_remote
            .entry(remote_branch.remote)
            .or_default()
            .insert(remote_branch.refname);
    }
    for remote_branch in remote_branches {
        per_remote
            .entry(remote_branch.remote.clone())
            .or_default()
            .insert(remote_branch.refname.clone());
    }

    for (remote, refnames) in per_remote {
        let mut command = vec!["push", "--delete", "--no-verify"];
        if dry_run {
            command.push("--dry-run");
        }
        command.push(&remote);
        let refnames: Vec<&str> = refnames.iter().map(|s| s.as_str()).collect();
        command.extend(refnames);
        subprocess::git(&command, Level::Trace)?;
    }
    Ok(())
}

fn detach_head(repo: &Repository, head: &LocalBranch, dry_run: bool) -> Result<()> {
    if dry_run {
        subprocess::git_dry_run(&["checkout", &head.refname], Level::Info);
        let object = repo.revparse_single(&head.refname)?;
        let commit = object.peel_to_commit()?;
        let short_id = object.short_id()?;
        let short_id = short_id.as_str().unwrap_or("");
        println!("Note: switching to '{}' (dry run)", head.refname);
        println!("You are in 'detached HED' state... blah blah...");
        println!(
            "HEAD is now at {} {} (dry run)",
            short_id,
            commit.summary().unwrap_or("")
        );
        Ok(())
    } else {
        subprocess::git(&["checkout", &head.refname], Level::Info)
    }
}

fn delete_local_branches(locals: &HashSet<LocalBranch>, dry_run: bool) -> Result<()> {
    if locals.is_empty() {
        return Ok(());
    }
    let names: Vec<&str> = locals.iter().map(|local| local.short_name()).collect();
    let mut command = vec!["branch", "--delete", "--force"];
    command.extend(names.iter().copied());
    if dry_run {
        subprocess::git_dry_run(&command, Level::Info);
        for name in names {
            println!("Delete branch {} (dry run).", name);
        }
        Ok(())
    } else {
        subprocess::git(&command, Level::Info)
    }
}

